          "hint": "unit rate",
          "subject": "math",
          "chapter": "ratio",
          "topic": "Direct proportion",
          "conceptId": "math_ratio_direct_proportion",
          "skillId": "math_ratio",
          "subskillId": "math_ratio_q1"
